INSERT INTO characters (slug,name,team,creator,owner_id,tags,appears_in,data,status,url_slug,created_at,updated_at) VALUES
('saboteur-the-menagerie','Saboteur','minion','Goodpart',NULL,NULL,'The Menagerie','{"slug":"saboteur-the-menagerie","name":"Saboteur","team":"minion","ability":"Each night, choose two players. The first character ability that targets or learns something about the first player now targets the second.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"Sorry. Plans change.","lede":"The Saboteur intercepts abilities and redirects them to whomever they please.","howToRun":["Remember that the Saboteur’s ability works only on abilities that target or learn something about the selected player. For instance, the Baku’s kills cannot be redirected since they are chosen by the Storyteller; and if the Grandchild dies, the Grandmother must also die too, since they are inextricably linked to their ability. Other roles, like the Dreamer, Empath, Gambler, Fortune Teller, etc. all work with the Saboteur as stated.","If the good team is in a terrible position, you can soften the power of the Saboteur in some instances. For instance, you may decide that the two names received as part of a Sage ping do not include the real Demon, but if evil is dominating, consider swapping out the red herring for the player the Saboteur chooses, and including the real Demon anyway."],"tips":["The Saboteur is an incredibly versatile Minion who can play a number of roles: you can spread misinformation by misdirecting Townsfolk abilities; you can protect your Demon by pushing certain abilities away from them; acting during game setup, you can fundamentally change the makeup of the game; and of course, you can take the reins away from your Demon and push kills on to better targets (or so you hope!)","The flipside to this is that without knowing what ability you are foisting on to another player, you may inadvertently muddy your own understanding of the town, or accidentally aid good players: so this is a Minion that naturally scales in power as the game progresses, and you understand more about the game state."],"bluffing":[],"fighting":["Given that the Saboteur redirects information, rather than outright poisoning it, you can reliably assume that for the most part, the information you are receiving is valid, even if inaccurate. A sabotaged Washerwoman, for instance, will receive a Townsfolk character that is indeed in play, but they may not be who you expect. A sabotaged Nightwatchman still sends out their signal, but a different player may receive it. If your information is pointing in a strange direction, ask yourself: why them? Perhaps you were misled to foster trust with an evil player - or perhaps you were a random target. Knowing who your information isn’t pointing to can still be valuable."],"examples":["Ginny is the Saboteur. They select themselves and their neighbour, the Empath. The Empath, whose neighbours are the Town Crier and the Saboteur, learns a zero.","Jin is the Dreamer. He selects his neighbour, learning that he is the Washerwoman or the Saboteur. The next day, he speaks with that player who claims to be the Juggler. He realises that he was selected by the Saboteur, redirecting information to themselves, claiming to be the Washerwoman."],"firstNight":19,"firstNightReminder":"The Saboteur chooses two players. Place the ''First'' token on the first player chosen , and the ''Second'' token on the second player chosen .","otherNight":8,"otherNightReminder":"The Saboteur chooses two players. Place the ''First'' token on the first player chosen , and the ''Second'' token on the second player chosen .","reminders":["First","Second"],"setup":false,"jinxes":[{"name":"Preacher","align":"good","text":"If the Saboteur is chosen by the Preacher, and they have redirected an ability from themselves to another player, another Minion is affected by the Preacher''s ability instead. The Saboteur learns this.","id":"preacher"},{"name":"Alchemist","align":"good","text":"If the Alchemist has the Poisoner ability and targets the Saboteur, the Saboteur is poisoned, even if they have redirected an ability from themselves to another player.","id":"alchemist"}],"image":"https://menagerie.towerrangers.net/images/sabe.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/sabg.png"}','published','the-menagerie/saboteur',datetime('now'),datetime('now')),
('wispr','Wispr','minion','Goodpart',NULL,NULL,'The Menagerie','{"slug":"wispr","name":"Wispr","team":"minion","ability":"You might register as adjacent to different players for good abilities. Once per game, at night, you may become drunk: a good player learns this.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"They start to bob and weave as if they''re excited you''ve come to join ''em, and it''s not until you''ve walked a ways that you notice they don''t seem to be growing much closer.","lede":"The Wispr projects itself to another point on the Grimoire to corrupt information.","howToRun":["This is a fairly mechanically heavy Minion in that it alters the physical layout of the Grimoire. If in person, consider placing a token between the two players to signify the Wispr is there. Otherwise, double check information you''re sending to ensure it''s accurate.","If the Wispr is targeted directly, remember where they are sitting so that it registers as appropriate.","Given that this power is at the Storyteller''s discretion, if town''s information is too ruined with the Wispr in play, consider misregistering it only some of the time to give good a chance to puzzle it out."],"tips":["The one big decision to make when playing as the Wispr is when to make yourself drunk. You can ruin the Tea Lady''s day, and cause the Empath to question reality, but at some point, you may accidentally be pushing on your own evil team. At that point, it''s time to pull the ripcord and get out of there: but know that a good player will learn that this happens. At that point, town will be on high alert for strange information, so the choice is tougher than you might think. Perhaps you slip out earlier than expected to cause chaos, or go a little later to implicate other players.","If a Wispr is not in play, perhaps it''s time to put out a fake Wispr call! Doing so will cause town to question their information to date, even though you know it to be true."],"bluffing":[],"fighting":["If you think a Wispr is in play, question everything. Otherwise reliable information like the Chef or Clockmaker can be wildly inaccurate due to the Wispr''s existence, but discerning where the Wispr might be registering from, rather than where they really are, is equally powerful information! If the Clockmaker did, indeed, get a 2, but players in those positions are confirmed by other means, perhaps something is awry about town''s information?","Additionally, the Wispr''s call is a signal to town to re-evaluate: use that opportunity to puzzle out what your new information looks like, in order to determine where the Wispr lies, but who - and what - they were covering."],"examples":["Lars is the Wispr neighbouring the Klutz and the Oracle, projecting themselves inbetween the Recluse and the Gossip. The Chef learns a 1.","Lochie is the Barber who learns that a Wispr has made themselves drunk. They announce it in the morning. The Empath, receiving a 1 overnight despite their neighbours not changing, determines that the Wispr is likely one of their living neighbours."],"firstNight":16,"firstNightReminder":"Place the ''Neighbour'' tokens on two adjacent players (not including the Wispr) . The Wispr may choose to make themselves drunk. If they do, remove the ''Neighbour'' tokens; choose a good player and show them the Wispr token.","otherNight":16,"otherNightReminder":"The Wispr may choose to make themselves drunk. If they do, remove the ''Neighbour'' tokens; choose a good player and show them the Wispr token.","reminders":["Drunk","Knows","Neighbour","Neighbour"],"setup":false,"jinxes":[{"name":"Preacher","align":"good","text":"If the Wispr is targeted by the Preacher''s ability, a good player (not the Preacher) sees the Wispr''s token :reminder:.","id":"preacher"},{"name":"Plague Doctor","align":"good","text":"If the Storyteller gains the Wispr''s ability, that ability is given to a living Minion instead.","id":"plaguedoctor"},{"name":"Alchemist","align":"good","text":"If the Alchemist gains the Wispr''s ability, they learn the name of one of their new neighbours.","id":"alchemist"}],"image":"https://menagerie.towerrangers.net/images/wise.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/wisg.png"}','published','the-menagerie/wispr',datetime('now'),datetime('now')),
('abomination','Abomination','demon','Goodpart',NULL,NULL,'The Menagerie','{"slug":"abomination","name":"Abomination","team":"demon","ability":"Each night*, choose a player: they die. You have two Minion abilities. [-1 Minion, -1 Outsider]","creator":"Goodpart","appearsIn":"The Menagerie","quote":"We are many. But we are one.","lede":"The Abomination trades voting power in town for additional Minion abilities.","howToRun":["Minion abilities given to the Abomination can be in-play."],"tips":["The days of coordinating Minion abilities are over - you are your own tool belt! With two Minion abilities in whatever combination the Storyteller chooses, you can cause chaos in a controlled manner, ensuring that you achieve the desired result 100% of the time. If there''s a pesky Ravenkeeper making your life difficult, you can guarantee they are poisoned upon their death - or if a powerful information role is getting a little too close, you can Pit Hag someone into a Sweetheart and kill them in one felled swoop.","Perhaps you might even have Minion abilities that are also in-play - meaning you can double up on those abilities, and make life that much harder for the good team. But beware: being overly enthusiastic with these abilities might out that an Abomination is in play."],"bluffing":[],"fighting":["Remember that the Abomination''s key weakness is a lack of Minions - with one less than usual, voting patterns become much more interesting to observe.","Keep an eye out for doubled Minion abilities to discern that an Abomination is in play."],"examples":["Amon is the Abomination with the abilities of the Witch and the Poisoner. They curse the Barber, then poison and kill the Ravenkeeper on Night 3.","Peter is the Mutant who is made mad as both the Seamstress and the Missionary. They realise that there is an Abomination in play. They break madness that same day and announce to the town that they were made mad twice, which can only be the result of an Abomination and Cerenovus targeting them at the same time."],"firstNight":2,"firstNightReminder":"Assign the Abomination with two on-script Minion abilities and inform the Abomination of the powers they have. They are performed in the corresponding point in the night order.","otherNight":37,"otherNightReminder":"The Abomination chooses a player.","reminders":["Dead"],"setup":true,"jinxes":[{"name":"Scarlet Woman","align":"good","text":"If the Abomination gains the Scarlet Woman ability, that ability is given to a living Minion instead.","id":"scarletwoman"},{"name":"Vizier","align":"good","text":"If the Abomination gains the Vizier ability, they are safe from execution only once.","id":"vizier"},{"name":"Mastermind","align":"good","text":"The Abomination cannot gain the Mastermind ability.","id":"mastermind"},{"name":"Boomdandy","align":"good","text":"The Abomination cannot gain the Boomdandy ability.","id":"boomdandy"},{"name":"Summoner","align":"good","text":"The Abomination cannot gain the Summoner ability.","id":"summoner"},{"name":"Efreet","align":"good","text":"The Abomination cannot gain the Efreet ability.","slug":"efreet"},{"name":"Necromancer","align":"good","text":"The Abomination cannot gain the Necromancer ability.","slug":"necromancer-the-menagerie"},{"name":"Goblin","align":"good","text":"If the Abomination gains the Goblin ability, they may lose this ability until dusk each night, and learn if this happens.","id":"goblin"}],"image":"https://menagerie.towerrangers.net/images/aboe.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/abog.png"}','published','the-menagerie/abomination',datetime('now'),datetime('now')),
('baku-the-menagerie','Baku','demon','Goodpart',NULL,NULL,'The Menagerie','{"slug":"baku-the-menagerie","name":"Baku","team":"demon","ability":"Each night*, choose a player: they die. One Townsfolk you speak to yields false information until dawn.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"If you hear the whispers that float on the wind, they may not hear your screams.","lede":"The Baku inverts the information of those they speak to.","howToRun":["This is a fairly intensive Demon to run because you have to track private conversations - a simple token reminder while you stay in town is generally a good way to handle this, as would be keeping private notes. Try to corrupt the information of the Townsfolk that would best balance the game state."],"tips":["Talk, talk, talk! Private conversations are your greatest weapon: with them, you corrupt information. Take on a role that is ready and willing to privately share information, and be enthusiastic about sharing it.","Alternatively, if you have specific Townsfolk on the table that you wish to cause problems for, limit your conversations to that select few, or bounce ideas off Outsiders and the evil team to ensure that the number of Townsfolk who can be impacted by your ability is slim without implicating yourself. Finding a balance between these two approaches is best, but the way you play the Baku is heavily influenced by town dynamics.","Note who you speak to during the day, as this will serve as a useful reminder of who is, and isn’t impacted by your ability."],"bluffing":[],"fighting":["The Baku’s greatest strength is in separating and flipping the information of players: so form a trusted coalition with the abundant information roles on the script, and form up!","Of course, you will need to be wary of the possibility that a Minion or the Baku itself is in that conversation: so while you may feel more obliged to share important info given the threat the Baku poses, oversharing will almost certainly lead to nasty consequences. If that happens, use it to your advantage by tracking who you spoke with to reverse engineer who may be evil. This becomes clearer as the game wears on, as players who die at night can track conversations and pin down the Demon.","You may even opt to stay out in the open, and never enter into private chats! If so, be prepared to be information-poor for most of the game, but at least you can (probably) trust your own information."],"examples":["Julien is the Baku. They speak with five players on Day 1: the Dentist, Savant, Colossus, Blackmailer and Saboteur. The Savant, after speaking with Julien, receives two wrong statements as their information.","Cerys is the Chef who learns true information on Night 1. They are immediately executed, and hears of a Savant who claims their information suggests their Chef 0 does not exist. Cerys asks the Savant to list who they spoke to the previous day, narrowing the Demon down to four possible players."],"firstNight":0,"firstNightReminder":"","otherNight":37,"otherNightReminder":"The Baku chooses a player.","reminders":["False Info","Dead"],"setup":false,"image":"https://menagerie.towerrangers.net/images/bake.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/bakg.png"}','published','the-menagerie/baku',datetime('now'),datetime('now')),
('chronos','Chronos','demon','Goodpart',NULL,NULL,'The Menagerie','{"slug":"chronos","name":"Chronos","team":"demon","ability":"Each night*, choose a player: they die. Townsfolk information swaps between true and false each night. Once per game, you may swap this order, and a good player learns this.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"Tick. Tock. Tick. Tock. Tock. Tick.","lede":"The Chronos causes information to swing between right and wrong.","howToRun":["So long as you are cognisant of the order in which information is right or wrong, the Chronos is fairly simple to run. Remember that, as with the Vortox, only Townsfolk are affected - and so characters like the Drunk still receive arbitrary information - poisoned or drunk Townsfolk do not."],"tips":["Crucially, you don''t start knowing whether your information is right or wrong - so get a gauge on what town''s information sounds like in order to fit in. Once you know your own cadence, it''s easy to play along.","When you choose to flip the script, however, is up to you. It''s recommended not to do this on the first night, as not only does it confirm your presence, but it is somewhat of a waste - but any point from then on is a reasonable time to switch it up. Just remember to keep up.","However, it is equally viable to give false information, especially in a town with a low number of information roles, in order to draw the line in the sand between the good and evil team. Without an abundance of ways to confirm info, who''s to say who''s right or wrong?"],"bluffing":[],"fighting":["Fighting the Chronos is no different to fighting a Demon like the Vortox - if you know your information is wrong, the opposite, therefore, must be correct. However, discerning whether a Chronos is in play - and which way the information leans - is much harder. You may not be able to risk not executing if a Vortox is also on script, but if you hear that someone received information about a Chronos at night, perhaps it''s time to re-evaluate.","Figuring out a Chronos is in play is the first step - reverse engineering your information to fit the Chronos'' cadence is the next. Puzzle that out, and you''re closer than ever to winning."],"examples":["Tony is the Chronos. Information starts out wrong. On Night 4, when information would be correct, Tony uses his ability, switching information back to being wrong. One good player learns that this has happened.","Lani is the Chambermaid who chooses the same two people on Night 2 and 3. She learns a 1 and a 2. The two players in question claim to be the unspent Seamstress and the Mime. She reasonably assumes that she was impacted by the Chronos on Night 2."],"firstNight":0,"firstNightReminder":"","otherNight":37,"otherNightReminder":"The Chronos chooses a player. . Swap the Tick (true) and Tock (false) tokens. They may also elect to use their ability. If they do, swap Tick (true) and Tock (false) tokens, and inform a good player of this.","reminders":["Tick (True)","Tock (False)"],"setup":false,"image":"https://menagerie.towerrangers.net/images/chre.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/chrg.png"}','published','the-menagerie/chronos',datetime('now'),datetime('now')),
('ein','Ein','demon','Goodpart',NULL,NULL,'The Menagerie','{"slug":"ein","name":"Ein","team":"demon","ability":"Each night*, choose a player: they die. On your first night, choose a player. The first time this happens, they become an evil Zwei. If you both live when 3 players live, evil wins. [-1 Minion]","creator":"Goodpart","appearsIn":"The Menagerie","quote":"Wer weiß? Der Teufel ist ein Eichhörnchen.","lede":"The Ein creates a second Demon, and uses them as a host in the event of their death.","howToRun":["Keep in mind that the Zwei must also be added on scripts containing the Ein in order for it to function. The only Demon available at setup is the Ein: the Zwei is selected on the Ein''s first night and cannot be selected on its own."],"tips":["The Ein''s strength is in numbers: while the Zwei doubles the amount of Demons on the Grimoire, making it more susceptible to Demon-finding roles like the Fortune Teller, it also creates an inbuilt Scarlet Woman to pass to should the need arise, and with its own ability to win when 3 players live, as well as the Zwei''s ability to poison its good-aligned neighbours (for better or worse), you have tremendous strength to start, which wanes substantially if it - or the Zwei - is killed. So do your best to protect your other half, since they are key in ensuring your power is maximised.","Remember that with one less Minion, you have less versatility overall, but the Zwei''s ability to poison is permanent as long as it lives, so use it to your advantage."],"bluffing":[],"fighting":["Two Demons on the board usually spells chaos for the town, but with an Ein in play, it''s business as usual. Double the Demons in play means double the opportunities to find them, so get killing! Executing players who are seen as a viable Demon candidate may weaken the Ein substantially, so don''t bide your time waiting for clarifying information, because you may not have the luxury of a final 3 to decide what is and what isn''t.","You are forced to play offensive to weaken the Ein and ultimately win the game, not just because of its unique win condition, but because your information will be fractured and seemingly unreliable. Once you know it''s in play, don''t delay."],"examples":["Maurice is the Ein, bluffing as the Mayor. He chooses Scott - the Zealot - to become the Zwei, who in turn poisons his good neighbours - the Librarian who ultimately confirms him as the Zealot, and the Klutz, who picks Maurice - but is sadly poisoned, oh no. Maurice protects Scott, wishing against enabling a Godfather kill at night, and Scott protects Maurice, supporting a Mayor victory. Maurice and Scott wake at the final 3, and congratulate each other on a job well done.","Brie is the General. She learns that evil is winning on Night 1. She correctly surmises that a powerful role has been selected by the Ein to become the Zwei. She notes one player in particular is especially protective of the player claiming to be the Empath and moves to execute them. She learns good is winning that night."],"firstNight":32,"firstNightReminder":"The Ein chooses a player.","otherNight":37,"otherNightReminder":"The Ein chooses a player.","reminders":["Dead"],"setup":true,"jinxes":[{"name":"Scarlet Woman","align":"good","text":"If the Zwei lives and the Ein dies, the Zwei becomes the Demon.","id":"scarletwoman"},{"name":"Barber","align":"good","text":"If the Barber dies, only the Ein is asked if they wish to swap characters. They may swap with the Zwei.","id":"barber"}],"image":"https://menagerie.towerrangers.net/images/eine.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/eing.png"}','published','the-menagerie/ein',datetime('now'),datetime('now')),
('hypnox','Hypnox','demon','Goodpart',NULL,NULL,'The Menagerie','{"slug":"hypnox","name":"Hypnox","team":"demon","ability":"On Night 1, choose players equal to Minions +1: they are poisoned. Each night*, choose a player: they die. You may instead turn chosen players into sober evil Minions & one sober evil Hypnox, & die. [No Minions, +1 Outsider]","creator":"Goodpart","appearsIn":"The Menagerie","quote":"What is this but a play on suggestibility? Their addled mind wants this. You can’t make someone do something they don’t want to do. Or can you?","lede":"The Hypnox starts alone, but can summon their evil Minions in an instant.","howToRun":["The Storyteller impacts a Hypnox game substantially in that you choose the Minions that rise once the Hypnox dies at night. Consider the game state at the time this happens, and ensure that you are choosing Minions that are the most fair - and fun - for the current game state. Choosing who becomes the Hypnox can be arbitrary, but also consider their position on the Grimoire: seating the new Hypnox next to a character like the Empath or Tea Lady may prove to be too difficult for the evil team to sell, and may end the game quickly, so you may want to consider putting more expendable Minions in those positions instead.","Also, try playing with the Hypnox and Lunatic on the same script - it''s great fun."],"tips":["This is a unique Demon in that you have no starting Minions. This places you in a precarious situation from the outset, however you can rest assured knowing that there is plenty of misinformation that will no doubt help to cast suspicion on others, and drive suspicion away from you. Use that to your advantage, sow doubt amongst the town, and then when the time is right, activate your ability and pass the torch to your newly risen evil team!","You can choose to play the Hypnox as a versatile poisoning character who, like a No Dashii, locks certain players into receiving misinformation, or into powers that misfire: but like the Imp, you have the ability to die safely if you’re uncomfortable with the level of suspicion aimed your way. Play it by ear, and judge the best time to make the jump.","You may consider telling your chosen players about their situation, and coordinate with them to begin framing worlds, but of course, you run the risk of being outed before you have a chance to pass to them - so be careful."],"bluffing":[],"fighting":["Like the No Dashii, finding players whose information feels at odds with the rest of town, or whose abilities don’t seem to be working as intended gives you a great insight as to whether a Hypnox is a) in play, and b) has chosen specific players. You may want to consider killing those players off early to prevent the Hypnox from gaining maximal benefit out of their ability.","Players who were once comfortable with execution that suddenly no longer want to die may have been turned by the Hypnox, so watch out for any strange behaviours, sudden changes of heart, or wildly incorrect information!","Crucially, if you know that a Hypnox has made the jump, you know that the evil team is down by one: track the possible source, and look to see who they align with the strongest."],"examples":["Ross is the Hypnox. He selects two players - the Noble and the Village Idiot - on Night 1. On night 3, Ross uses his ability and dies at night. The Noble becomes the Hypnox, and the Village Idiot becomes the Witch.","Ryan is the Acrobat. He selects the Noble on Night 2 and dies. Town moves to execute the Noble under suspicion that they might be chosen by the Hypnox."],"firstNight":32,"firstNightReminder":"Wake the Hypnox, and allow them to choose players equal to the number of Minions +1.","otherNight":37,"otherNightReminder":"The Hypnox chooses a player.","reminders":["Chosen","Chosen","Chosen","Chosen","Dead","Is The Demon"],"setup":true,"jinxes":[{"name":"Summoner","align":"good","text":"A Hypnox can not create a Summoner. If the Summoner creates a Hypnox, poisoned players are arbitrarily selected; the Summoner must be one of them.","id":"summoner"}],"image":"https://menagerie.towerrangers.net/images/hype.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/hypg.png"}','published','the-menagerie/hypnox',datetime('now'),datetime('now')),
('patient-zero','Patient Zero','demon','Goodpart',NULL,NULL,'The Menagerie','{"slug":"patient-zero","name":"Patient Zero","team":"demon","ability":"Each night*, the nearest healthy, good neighbour of the most recently killed executee dies: the other is poisoned. Each day, if no living player is executed, evil wins.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"Subject is showing remarkable promise. We shall inject another dose and apply 10,000 volts in the hope that reanimation might occur. Subject’s extremities are black and atrophied - our data did not predict this. To attending partners: caution.","lede":"Patient Zero spreads poison and death throughout town.","howToRun":["You have an incredible amount of control over the game state: given that a good living neighbour of the recent executed must be killed, and the other must be poisoned, what you choose to inflict on each may lead to game-solving information. Assess the game state and use discretion to ensure balance is being maintained. For instance, if good is doing particularly well, you can hide evil neighbours with poisoning, and of course, if evil is dominating, it may be useful to out a Minion to balance out the numbers. This is a very dynamic Demon that can move through a game quickly, so good luck!"],"tips":["You have no control over your kills, except for trying to direct where nominations are pointing each day. As such, you and your Minions need to play an active role in seeding bad information, drawing suspicion towards players of your choosing, and ensuring you get kills on the board by other means.","Of course, your additional win condition, unique to that of the Vortox, demands that living players be executed each day, so there is no opportunity to sacrifice a dead body in the same way - which in turn prevents town from finding evil players by simply killing the same corpse over and over. This means that town’s ability to discern who is evil is limited, so push that advantage! Claim to be a poisoned neighbour of a recently killed good player, and do your best to verify poisoned players’ claims if it would help your team.","This in turn should cause players near recent executees to examine their information and doubt what they have received, so feel free to reach out to them and provide reasons as to why their sober, healthy information might not be.","Remember that you (probably) know your evil team, and you can figure out who is poisoned with bad info from who has died in the night, so you should always have the informational advantage."],"bluffing":[],"fighting":["Vote wisely. Patient Zero can only kill good, sober living neighbours of the recent executee, so if you have located specific characters that are a “good” execution for the day and are willing to hedge your bets, go through with it. This limits Patient Zero’s ability to poison ongoing information or snuff out active abilities that would otherwise protect town. If an execution goes through on a player you are less happy with killing, take care to examine what information comes out of the night - but more specifically, examine who is impacted. Players who are poisoned or killed by Patient Zero in the night are confirmably good and once sober, so use that to your advantage, and if there are obvious gaps, you may have found your next execution!"],"examples":["Noor is Patient Zero. On Day 1, they nominate and execute the Cartographer. The Cartographer''s neighbour dies that night, and their other neighbour, the Mechanical Man, is poisoned.","Quentin is the Mutant sitting two seats away from the most recently executed player. They claim to be the Mutant on Day 3, and is not executed. Quentin assumes they are poisoned, and nominates the other neighbour of the most recently executed player, believing them to be evil."],"firstNight":0,"firstNightReminder":"","otherNight":37,"otherNightReminder":"All effects that took place last night are removed. The player marked ''Dead'' is killed . The player marked ''Poisoned'' is poisoned .","reminders":["Dead","Poisoned"],"setup":false,"jinxes":[{"name":"Soldier","align":"good","text":"The Soldier is safe from Patient Zero’s abilities: if one would target a Soldier, it jumps to the next player over instead.","id":"soldier"},{"name":"Tea Lady","align":"good","text":"If the Tea Lady’s ability would activate via execution, this fulfils Patient Zero’s condition around execution. If it would activate at night, good neighbours are safe from Patient Zero’s abilities, but effects jump to the next player over instead.","id":"tealady"},{"name":"Monk","align":"good","text":"The player protected by the Monk is safe from Patient Zero: poisoning or death jumps to the next player over instead.","id":"monk"}],"image":"https://menagerie.towerrangers.net/images/pate.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/patg.png"}','published','the-menagerie/patient-zero',datetime('now'),datetime('now'));